UPDATE questions SET explanation = '本文には、これらの都市が繁栄したのは "largely because of their strategic locations rather than their own manufacturing output"(自らの生産力よりも主に戦略的な立地のおかげ)だとあります。' WHERE id = 'q-read-silkroad-4';
UPDATE questions SET explanation = 'この語句は、同じ文の前半で述べられているシルクロードのネットワークの衰退を指しています。' WHERE id = 'q-read-silkroad-5';
UPDATE questions SET explanation = '本文では香辛料、製紙技術、仏教の伝播について触れられていますが、火器については言及されていません。' WHERE id = 'q-read-silkroad-6';
UPDATE questions SET explanation = '本文はC4光合成の仕組みと、それが通常のC3光合成と比べてなぜ高温乾燥環境で有利になるのかを説明しています。' WHERE id = 'q-read-photosynthesis-1';
