UPDATE questions SET explanation = '本文は「海の民」による襲撃、長期の干ばつ、貿易網の崩壊に触れていますが、大規模な火山噴火については述べていません。' WHERE id = 'q-read-bronze-age-6';
UPDATE questions SET explanation = '本文は損失回避について説明し、それが合理的な経済モデルから外れた行動をどのように引き起こすかの例をいくつか挙げています。' WHERE id = 'q-read-loss-aversion-1';
UPDATE questions SET explanation = '本文に "feel the pain of a loss roughly twice as intensely as the pleasure of an equivalent gain" とあるように、人は損失の痛みを同額の利益の喜びの約2倍強く感じるとされています。' WHERE id = 'q-read-loss-aversion-2';
