UPDATE questions SET explanation = '本文は地磁気、太陽や星の位置、目印や匂いに触れていますが、他の鳥からの電波信号については述べていません。' WHERE id = 'q-read-bird-navigation-6';
UPDATE questions SET explanation = '本文は組み立てライン(アセンブリーライン)が製造効率をどう変え、産業全体に長期的な影響を与えたかを説明しています。' WHERE id = 'q-read-assembly-line-1';
UPDATE questions SET explanation = '本文には工場が "reduced the time required to build a single car to roughly ninety minutes" とあります。' WHERE id = 'q-read-assembly-line-2';
UPDATE questions SET explanation = '"Monotony of repetitive tasks" は、単純作業の反復性を表しています。' WHERE id = 'q-read-assembly-line-3';
UPDATE questions SET explanation = '本文には賃金上昇の理由として "in part to reduce the high turnover caused by the monotony of repetitive tasks" とあります。' WHERE id = 'q-read-assembly-line-4';
UPDATE questions SET explanation = 'この文は、組み立てラインによる効率性の向上と、それが同時に受けた批判とを対比しています。' WHERE id = 'q-read-assembly-line-5';
UPDATE questions SET explanation = '本文は建造時間の短縮、価格低下、単純労働化への批判に触れていますが、工場労働の完全な消滅については述べていません。' WHERE id = 'q-read-assembly-line-6';
UPDATE questions SET explanation = '本文は、永久凍土の融解が二酸化炭素とメタンを放出し、温暖化を加速させるフィードバックループを生み出す仕組みを説明しています。' WHERE id = 'q-read-permafrost-1';
