UPDATE questions SET explanation = '「Long-dormant organic material」は、長期間活動を停止した(=分解が進んでいない)物質を表しています。' WHERE id = 'q-read-permafrost-3';
UPDATE questions SET explanation = '本文には、新たに放出されるこの炭素は「以前は閉じ込められており、過去の気候予測には織り込まれていなかった("was previously locked away and not accounted for in earlier climate projections")」とあります。' WHERE id = 'q-read-permafrost-4';
UPDATE questions SET explanation = 'この文は、インフラの下にある地面(永久凍土)が融解し、不均一に沈下していく様子を説明しています。' WHERE id = 'q-read-permafrost-5';
UPDATE questions SET explanation = '本文では融解の影響を受けるものとして建物・道路・パイプラインが挙げられていますが、海流については言及がありません。' WHERE id = 'q-read-permafrost-6';
UPDATE questions SET explanation = '本文は、ハンムラビ法典の内容と構成、そして1901年の再発見の経緯を説明しています。' WHERE id = 'q-read-hammurabi-1';
UPDATE questions SET explanation = '本文に「法典は282の個別の法から成る("consists of 282 individual laws")」とあります。' WHERE id = 'q-read-hammurabi-2';
