UPDATE questions SET explanation = '本文には、実際に科される罰は「加害者と被害者双方の社会的地位に大きく左右されることが多かった("often depended heavily on the social status of both the offender and the victim")」とあります。' WHERE id = 'q-read-hammurabi-4';
