UPDATE questions SET explanation = 'この段落は、地衣類が大気汚染物質に敏感であることが、大気質の指標として利用される理由になっていると説明しています。' WHERE id = 'q-read-lichen-5';
UPDATE questions SET explanation = '本文では熱帯雨林・北極の裸岩・樹皮が地衣類の生育環境として挙げられていますが、海底については言及がありません。' WHERE id = 'q-read-lichen-6';
UPDATE questions SET explanation = '本文は、ジェンナーの実験、「種痘(vaccination)」という用語の誕生、そしてその後の世界的な普及という流れを追っています。' WHERE id = 'q-read-vaccination-1';
UPDATE questions SET explanation = '本文には、民間伝承では牛痘にかかったことのある乳搾りの女性たちは「天然痘にほとんどかからなかった("rarely contracted smallpox at all")」と信じられていたとあります。' WHERE id = 'q-read-vaccination-2';
