UPDATE questions SET explanation = '本文には、人痘接種法は天然痘の膿を用いており、「時に致命的な感染を引き起こすことがあった("sometimes caused fatal infections")」とあります。' WHERE id = 'q-read-vaccination-4';
UPDATE questions SET explanation = '「This procedure」は、ジェンナーが少年に対して行ったばかりの、牛痘を用いた接種法を指します。' WHERE id = 'q-read-vaccination-5';
