UPDATE questions SET explanation = '本文は、産業革命期の急激な都市化が劣悪な生活環境を生み、やがて公衆衛生改革へとつながっていった経緯を追っています。' WHERE id = 'q-read-urbanization-1';
UPDATE questions SET explanation = '本文には、マンチェスターは「1770年には人口約2万5千人の小さな市場町だったが、数十年のうちに数十万人規模の都市へと成長した("grew from a modest market town of about twenty-five thousand people in 1770 to a city of several hundred thousand")」とあります。' WHERE id = 'q-read-urbanization-2';
UPDATE questions SET explanation = '成長が行政のサービス提供能力を「outpaced(上回った)」というのは、行政の対応が追いつく速さを成長が超えてしまったという意味です。' WHERE id = 'q-read-urbanization-3';
UPDATE questions SET explanation = '本文には、多くの世帯が一つの水源やトイレを共有しており、それが疾病の蔓延にとって理想的な状況を生み出したとあります。' WHERE id = 'q-read-urbanization-4';
